-- Original guidance. Classic facts are a baseline, not verified Octo recipe unlocks.
-- Actual client skill, recipe color, reagents and tools override these suggestions.
local G=OctoGuide
local D={order={'Alchemy','Blacksmithing','Enchanting','Engineering','Jewelcrafting','Leatherworking','Tailoring','Mining','Herbalism','Skinning','Cooking','Fishing','First Aid','Survival'},professions={}}
G.ProfessionData=D
local base='https://www.wow-professions.com/classic/'
local function add(name,kind,tool,rows,extra)
 local slug=string.gsub(string.lower(name),' ','-')
 local p={name=name,kind=kind,tool=tool,bands=rows,source=base..slug..'-leveling-guide-classic-wow',confidence='Classic baseline; verify with Octo trainer and live recipes'}
 for k,v in pairs(extra or {}) do p[k]=v end
 D.professions[name]=p
end
-- Each row is a skill ceiling and an original concise suggestion, not a craft count.
add('Alchemy','craft','Buy empty vials; keep intermediate potions.',{{60,'Compare Minor Healing Potion with other orange learned potions.'},{110,'Use available early herbs; Lesser Healing and Wisdom potions are candidates.'},{155,'Compare Healing and Mana potions. Keep useful intermediate potions.'},{210,'Compare Greater Healing, Agility and Defense potions using your herbs.'},{265,'Compare Superior Healing and later trainer potions.'},{300,'Compare Major Healing and available late recipes; check vendor recipes.'}})
add('Blacksmithing','craft','Blacksmith Hammer and anvil. Preserve stones and parts.',{{75,'Use stone crafts and simple copper equipment; keep grinding stones.'},{150,'Compare bronze equipment and coarse/heavy stone crafts.'},{200,'Compare iron equipment and steel recipes; preserve required components.'},{250,'Compare mithril equipment and dense/solid stone crafts.'},{300,'Compare thorium equipment with learned alternatives; verify specializations.'}})
add('Enchanting','enchant','Keep the correct enchanting rod. Disenchant only items you choose.',{{75,'Compare orange bracer enchants with the dust you already own.'},{150,'Compare early dust/essence enchants; check the next rod requirements.'},{225,'Use your available dust and essences; preserve rod components.'},{300,'Compare late learned enchants. Vendor recipes and rods can block progress.'}})
add('Engineering','craft','Tools and anvil vary by recipe. Preserve parts for later crafts.',{{75,'Compare rough blasting powder, bolts and copper parts.'},{150,'Use bronze parts and explosives; keep tubes and frameworks.'},{225,'Compare iron/steel and mithril parts. Do not sell components blindly.'},{300,'Compare late mithril/thorium recipes; respect your specialization.'}})
add('Jewelcrafting','craft','Check Jeweler tools in your recipe window; later tools need Engineering.',{{75,'Compare paper, copper rings and gemstone clusters. Keep rings and paper.'},{150,'Compare bronze/silver rings and coarse paper; retain intermediate rings.'},{225,'Compare gold/iron/mithril rings, heavy paper and learned jewelry.'},{300,'Compare thorium jewelry and dense paper; verify vendor recipes and tools.'}},{source='https://octowow.st/forum/viewtopic.php?t=1664',confidence='Octo community baseline; live recipe data is authoritative',trainers={Horde={'Asoran','Kalnag','Gulmire Fartower'},Alliance={'Brandon Fencer','Kalvan Fencer','Mayva Togview'},neutral={'Fanzy Sparkspring'}},artisan='Fanzy Sparkspring, Steamwheedle Port (Tanaris); check your actual training requirements.'})
add('Leatherworking','craft','Keep hides and intermediate leather; use Skinning where practical.',{{75,'Compare light leather crafts and armor kits.'},{150,'Compare medium leather recipes and available hides.'},{225,'Compare heavy/thick leather recipes and armor kits.'},{300,'Compare thick/rugged leather recipes; verify specialization and patterns.'}})
add('Tailoring','craft','Keep cloth bolts for later crafts; thread is a vendor material.',{{75,'Turn linen into bolts, then compare learned linen clothes.'},{150,'Compare wool and silk recipes; keep useful bolts.'},{225,'Compare silk and mageweave recipes using available cloth.'},{300,'Compare mageweave/runecloth recipes; check patterns and thread.'}})
add('Mining','gather','Mining Pick; Find Minerals.',{{65,'Mine Copper in starting areas; smelting can also give skill.'},{125,'Look for Tin and Silver; compare learned smelting recipes.'},{175,'Look for Iron and Gold in suitable areas.'},{245,'Look for Mithril and Truesilver.'},{300,'Look for Thorium. Rich veins require higher skill; avoid dangerous areas.'}},{category='ore',tracking='Find Minerals'})
add('Herbalism','gather','Find Herbs. Choose areas appropriate to your character level.',{{50,'Gather Peacebloom, Silverleaf and eligible Earthroot.'},{100,'Gather eligible Mageroyal, Briarthorn and Bruiseweed.'},{170,'Gather eligible Kingsblood, Liferoot and later herbs.'},{230,'Look for eligible Goldthorn, Khadgar\'s Whisker and later herbs.'},{300,'Look for eligible high-level herbs in safe areas.'}},{category='herb',tracking='Find Herbs'})
add('Skinning','skin','Skinning Knife. Only skinnable corpses can be gathered.',{{75,'Skin eligible beasts in your current starting area.'},{150,'Use appropriate beasts around level 15-25; verify corpse eligibility.'},{225,'Use appropriate beasts around level 25-40; keep travel short.'},{300,'Use appropriate higher-level beasts. Safety comes before proximity.'}})
add('Cooking','craft','Some recipes need a cooking fire. Compare fish and meat you own.',{{75,'Compare early meat recipes; Fishing can supply an alternative.'},{150,'Compare available meat and fish recipes; learn the next rank/book.'},{225,'Compare middle-level fish/meat. Preserve materials for Artisan training.'},{300,'Complete required training, then compare late learned fish/meat recipes.'}},{artisan='Check the faction cooking lead-in and Dirge Quikcleave in Gadgetzan for Artisan cooking.'})
add('Fishing','fish','Fishing Pole; use a lure if catches fail. Pools are optional for leveling.',{{75,'Fish successfully in safe starting-zone open water.'},{150,'Keep using water where catches succeed; pair catches with Cooking.'},{225,'Learn the next rank/book and stay in safe, suitable water.'},{300,'Complete required Artisan training. Catch success matters more than pool proximity.'}},{category='fish',artisan='Check Nat Pagle in Dustwallow Marsh for Artisan fishing; verify level and skill requirements.'})
add('First Aid','craft','Keep cloth for bandages and training. No gathering nodes for cloth.',{{40,'Compare Linen Bandage.'},{80,'Compare Heavy Linen Bandage.'},{115,'Compare Wool Bandage.'},{150,'Compare Heavy Wool and Silk Bandage; obtain the Expert book.'},{180,'Compare Silk Bandage.'},{210,'Compare Heavy Silk Bandage; verify the instruction book.'},{225,'Compare Mageweave Bandage; prepare for Artisan training.'},{260,'Compare Mageweave and Heavy Mageweave Bandage after training.'},{290,'Compare Runecloth Bandage.'},{300,'Compare Heavy Runecloth Bandage.'}},{artisan='Artisan: faction Triage training, Doctor Gregory Victor (Horde) or Doctor Gustaf VanHowzen (Alliance). Verify level/skill with the trainer.'})
add('Survival','craft','Whittle and Woodcutting Axe. Some recipes require fire or anvil.',{{10,'Compare Dim Torches. Woodcutting becomes available at skill 5.'},{35,'Prepare simple stick bundles and compare Crude Walking Sticks.'},{50,'Compare Simple Slingshots; keep bundles for later recipes.'},{75,'Compare Weak Healing Salve with tree gathering.'},{125,'Compare Crude Fishing Rod and Simple Fishing Lure; keep useful lures.'},{175,'Compare bright-wood bundles, nets and learned traps. Preserve nets.'},{225,'Compare shade-wood recipes and rations; prepare the Artisan materials.'},{275,'Compare tropical-wood recipes and learned alternatives.'},{300,'Compare star-wood bundles and late fishing traps; preserve their components.'}},{source='https://octowow.st/forum/viewtopic.php?p=8840',confidence='Octo community baseline; wood skill-up cutoffs are not verified',category='wood',tracking='Find Trees',trainers={Horde={'Thonk','Brakan','Swampwalker Krug'},Alliance={'Nallaeth','Eissinn Cragbelly','Nerean Stagtree'},neutral={'Rufus Hardwick'}},artisan='Rufus Hardwick in Stranglethorn Vale: To Survive in the Jungle. Check the required crafted materials before traveling.'})
